<?php $rows=$pdo->query('SELECT h.*,u.name user_name FROM status_histories h JOIN users u ON u.id=h.changed_by ORDER BY h.changed_at DESC LIMIT 300')->fetchAll(); ?>
<div class="card panel"><h3>Riwayat Perubahan Status</h3><table><thead><tr><th>Waktu</th><th>Entitas</th><th>ID</th><th>Status Lama</th><th>Status Baru</th><th>Catatan</th><th>Pengguna</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['changed_at'])?></td><td><?=e($r['entity_type'])?></td><td><?=$r['entity_id']?></td><td><?=e($r['old_status']??'-')?></td><td><span class="status <?=status_class($r['new_status'])?>"><?=e($r['new_status'])?></span></td><td><?=e($r['notes'])?></td><td><?=e($r['user_name'])?></td></tr><?php endforeach;?></tbody></table></div>
